"""Tests for InMemoryTaskRepository and normalize_tags."""

from datetime import datetime, timezone

import pytest

from tasks_api.models import Tag, Task, TaskStatus
from tasks_api.repository import InMemoryTaskRepository, normalize_tags


class TestInMemoryTaskRepository:
    @pytest.fixture()
    def repo(self):
        return InMemoryTaskRepository()

    def _make_task(self, repo, title="Test"):
        tid = repo.next_id()
        return Task(id=tid, title=title, created_at=datetime(2025, 1, 1, tzinfo=timezone.utc))

    def test_next_id_increments(self, repo):
        assert repo.next_id() == 1
        assert repo.next_id() == 2

    def test_add_and_get(self, repo):
        task = self._make_task(repo)
        repo.add(task)
        retrieved = repo.get(task.id)
        assert retrieved is task

    def test_add_duplicate_raises(self, repo):
        task = self._make_task(repo)
        repo.add(task)
        with pytest.raises(ValueError, match="already exists"):
            repo.add(task)

    def test_get_missing_returns_none(self, repo):
        assert repo.get(999) is None

    def test_list_returns_all(self, repo):
        t1 = self._make_task(repo, "A")
        t2 = self._make_task(repo, "B")
        repo.add(t1)
        repo.add(t2)
        items = list(repo.list())
        assert len(items) == 2

    def test_update_existing(self, repo):
        task = self._make_task(repo)
        repo.add(task)
        task.title = "Updated"
        repo.update(task)
        assert repo.get(task.id).title == "Updated"

    def test_update_missing_raises(self, repo):
        task = self._make_task(repo)
        with pytest.raises(KeyError):
            repo.update(task)

    def test_delete_existing(self, repo):
        task = self._make_task(repo)
        repo.add(task)
        assert repo.delete(task.id) is True
        assert repo.get(task.id) is None

    def test_delete_missing(self, repo):
        assert repo.delete(999) is False


class TestNormalizeTags:
    def test_deduplicates(self):
        result = normalize_tags([Tag("foo"), Tag("FOO"), Tag("bar")])
        names = [t.name for t in result]
        assert names == ["foo", "bar"]

    def test_strings_converted(self):
        result = normalize_tags(["Hello", "world"])
        assert all(isinstance(t, Tag) for t in result)
        assert result[0].name == "hello"

    def test_empty_input(self):
        assert normalize_tags([]) == []
